 * DB の mtb_event_scale.id → デザイン bundle が想定する event_scale_id のマッピング。
 * 設計書では 1=おすすめ / 2=定番 / 3=特別 / 4=大型 だが、bundle 側は 1=大型 / 2=特別 / 4=おすすめ / else=デイリー を前提とするため変換する。
 */
private const SCALE_ID_DB_TO_BUNDLE = [
    4 => 1, // 大型
    3 => 2, // 特別
    1 => 4, // おすすめ
    // DB id=2 (定番) は bundle 側で else (= デイリー) 扱いになるため変換テーブルから除外
];
